{
  "version": "2.1.0",
  "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
  "runs": [
    {
      "tool": {
        "driver": {
          "name": "Canary",
          "version": "0.1.0",
          "informationUri": "https://github.com/bop-clocktower/canary",
          "rules": [
            {
              "id": "canary/test-generation",
              "name": "TestGeneration",
              "shortDescription": {
                "text": "AI-generated test file"
              },
              "helpUri": "https://github.com/bop-clocktower/canary"
            },
            {
              "id": "canary/test-execution",
              "name": "TestExecution",
              "shortDescription": {
                "text": "Automated test execution result"
              },
              "helpUri": "https://github.com/bop-clocktower/canary"
            }
          ]
        }
      },
      "results": [
        {
          "ruleId": "canary/test-generation",
          "message": {
            "text": "Generated playwright test (e2e_ui) \u2014 tests/e2e/orders.spec.ts"
          },
          "level": "none",
          "locations": [
            {
              "physicalLocation": {
                "artifactLocation": {
                  "uri": "tests/e2e/orders.spec.ts",
                  "uriBaseId": "%SRCROOT%"
                }
              }
            }
          ],
          "properties": {
            "framework": "playwright",
            "test_type": "e2e_ui",
            "reasoning": [
              "matched playwright config",
              "e2e intent"
            ],
            "quality": {
              "score": 87,
              "grade": "B"
            }
          }
        }
      ]
    }
  ]
}

